INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Catopia: Rush', 'Catopia: Rush drops players into a fantasy world filled with monsters and dungeons. You lead a raid party of heroic cats, each with their own unique roles and skills. Launch arrows from your bow or blast bolts of fire magic with super easy, one-handed controls. Simply stop to shoot, and move to dodge as your team follows you! Anyone can play but mastery is encouraged through optional harder difficulties.' FROM games WHERE igdb_id = 152070 ON CONFLICT (game_id, language_code) DO NOTHING;
