INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pressure--1', 186086, '2021-04-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4b89.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scwgph.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pressure', 'Deeper and deeper into an infinite basement of increasingly difficult enemies, how deep can you go? Pressure is a simple, high-score based arcade FPS with easy to learn but rewarding projectile mechanics. Search the maze-like floors for the green zone to drop into the next level and receive half your health back. Chaining combos of kills, hitting long range shots or bouncing shots off walls into enemies will also heal you. Enemies will hit harder and increase their spawns as you reach deeper and deeper floors. Watch out for harder enemy types as you go deeper.' FROM games WHERE igdb_id = 186086 ON CONFLICT (game_id, language_code) DO NOTHING;
