INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tasomachi: Behind the Twilight', 'Yukumo is a young girl who travels around in her airship, her pride and joy. When visiting a particular Far Eastern town to run some errands her airship suddenly breaks down. She decides to explore the town to search for parts for repair; however, the town has fallen silent with no trace of the people who live there, the only inhabitants being a strange cat-like species...INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 121481 AND ge.slug = 'platform' ON CONFLICT DO NOTHING;
