INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Burn. Pulse. Detach.', 'Burn Pulse Detach is a project written over a couple of years, in bits and pieces, and finally stitched together to form the project above, reflections on disjointed chaotic jumbles of potentially disordered/non-neurotypical thoughts, usually stemming from moments of emotional extremity.' FROM games WHERE igdb_id = 143115 ON CONFLICT (game_id, language_code) DO NOTHING;
