INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-simpsons--4', 330108, '2021-11-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9cl7.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Simpsons', 'Redefining family game rooms, game caves, and even home offices, Arcade1Up game cabinets have quickly become absolute must-haves for retro gaming enthusiasts and pop-culture collectors; they play great, look great, and are instant conversation pieces. Exactly how you remember it from the early ‘90s, play as Homer, Marge, Bart, and Lisa, taking on swarms of Springfield’s cast of characters. Four simultaneous players, endless animation inspired fun. Ready to team up for some remote play? The Simpsons home arcade game is equipped with Live WIFI; yes, you can fight your way through each level with the help of fellow retrogamers playing from their own cabinets! Oh, and you want to switch it up a bit? You got it. Also in this cabinet is The Simpsons Bowling! Beautifully bold cabinet artwork (with a matching riser!), stunningly vibrant graphics, this is an arcade cabinet that would make any retrogamer envious. Invite The Simpsons into your home, with this arcade cabinet from Arcade1Up!' FROM games WHERE igdb_id = 330108 ON CONFLICT (game_id, language_code) DO NOTHING;
