INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pizza Break', 'Pizza Break is an arcade game that lets the user knock out Pizza themed items with a unique Pizza Box paddle and pizza slice ball. Unique Animated levels, Mini-Bosses and Powerups to collect as you progress through the levels. Thirty Levels to compete in and battle mini bosses on your way to victory. Single player fun and arcade style entertainment.' FROM games WHERE igdb_id = 164307 ON CONFLICT (game_id, language_code) DO NOTHING;
