INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Bike Ride to the Creek', 'I lived in rural North Carolina during my elementary school years, and loved to explore the forests, ponds, and trails that surrounded my neighborhood. These places are all but gone now due to encroaching development, so making a game that retraces the trail to the creek has been a way for me to preserve and revisit some really happy childhood memories.' FROM games WHERE igdb_id = 266135 ON CONFLICT (game_id, language_code) DO NOTHING;
