INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Decaying Delicacy', 'Collect keys to unlock gates to get those delicious delicacies while avoiding strange threats in a 2.5D arcade collection game, or at least that''s the game some of the time. Read your diary, or don''t. The game has several different endings based on your performance, and a number of alternative paths based on your choices and how you''re doing.' FROM games WHERE igdb_id = 146493 ON CONFLICT (game_id, language_code) DO NOTHING;
