INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jo''s House', 'Jo''s house is a maze building game where you must rearrange the furniture of the HQ Residential House to create the longest path from Jo''s bed to one of the exits (front door, back door or garage). At night Jo will start rolling around the house to either attack you, eat a pie or exit the house. Your goal is to survive 3 nights doing the following 2 things: #1: Don''t get hit by Jo. #2: Don''t let Jo leave the house.' FROM games WHERE igdb_id = 177391 ON CONFLICT (game_id, language_code) DO NOTHING;
