INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Graffiti Smash', 'Slingshot to paint surfaces and get power boosts. Enjoy PvP matches via a real-time online battle system. Co-op with friends to clear dungeons and beat bosses. Enjoy a script of 1 million plus words that tells stories about the bonds and dynamics between people in a post-apocalyptic world!' FROM games WHERE igdb_id = 98559 ON CONFLICT (game_id, language_code) DO NOTHING;
