INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disenchantment Heart', '祛魅·格心（祛魅3）是一款小清新像素风回合制角色扮演游戏，祛魅系列历代作品第三部。剧情故事发生在二代入灭事件结束后的东方异大陆。艰难的生存于市井之中酷爱讲鬼故事的贫苦少女，真情感动披坚执锐勇猛御敌的巡捕营参将？温婉善良双剑乖巧的少女能否寻得真凶手刃仇敌？由高人驯养获得真传的猫妖会成为合格的圣痕守护者吗？得传叶灵流刀法灵武士一生守护嗣潘王？喜欢蹂躏欺辱各种非人类生物的降妖师...不可描述？？？' FROM games WHERE igdb_id = 161161 ON CONFLICT (game_id, language_code) DO NOTHING;
