INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Secret Challenge', 'Secret Challenge is a multiplayer party game for 2 to 8 players where each participant receives a secret task to complete without being detected. Challenges include actions such as making another player say a specific word, pretending to sneeze, hiding an object, or encouraging someone to sing. Players aim to complete their tasks while remaining inconspicuous, as others try to identify who has a challenge. The game is played in person using a mobile device and includes optional challenge packs that introduce different themes and scenarios for varied gameplay.' FROM games WHERE igdb_id = 342494 ON CONFLICT (game_id, language_code) DO NOTHING;
