INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'There Will Be No Turkey This Christmas', 'Christmas is coming, and your goal is to spoil it! After all, you are the turkey! Hide in the barrel so you won''t be seen by your enemies. Be stealthy! You are escaping, after all. Seek the keys to make your way to freedom and escape all 7 members of the Silva family. Pass through hidden tunnels in the house so the enemies do not see you! Collect items to make new skins available. Take on the 30 levels and win the challenge of not becoming a roast turkey.' FROM games WHERE igdb_id = 185783 ON CONFLICT (game_id, language_code) DO NOTHING;
