INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'HardLander', 'HardLander is a tough-as-nails "Rocket Wrestling" arena designed for up to 4 players. Invite three of your friends to compete for bragging rights and couch cred in what might be the most advanced rocket wrestling simulation ever created! Practice your piloting expertise through 40 punishing challenge courses that will be sure to have you throwing your controller across the room as you hone your skills.' FROM games WHERE igdb_id = 95327 ON CONFLICT (game_id, language_code) DO NOTHING;
