INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warhammer 40,000: Lost Crusade', 'Warhammer 40,000: Lost Crusade is an online MMO strategy mobile game set in the Warhammer 40,000 universe. As a Space Marine Force Captain, command a Battle Barge, train elite troops, recruit legendary heroes and play with allies to defeat the Forces of Chaos and conquer your part of the galaxy! For in the grim darkness of the far future, there is only war. "For the Emperor!"' FROM games WHERE igdb_id = 154795 ON CONFLICT (game_id, language_code) DO NOTHING;
