INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pocoyo Party', 'Come play with Pocoyo and friends in these 6 great educational mini-games where you will learn letters, numbers, colours and much more! Win rewards by completing levels: puzzles, pictures and exclusives episodes of Pocoyo that you can watch any time. Play with all the main characters in the series in multiplayer mode for up to 4 players. Pocoyo, Nina, Pato and Elly await you!' FROM games WHERE igdb_id = 144821 ON CONFLICT (game_id, language_code) DO NOTHING;
