INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('unblock-brick', 147488, '2021-03-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co59eo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9lh.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unblock Brick', '* HOW TO PLAY: - Horizontal blocks can be moved only side-wards - Vertical blocks can be moved up and down - Move the red block to the exit Unblock Brick is a popular and very addictive block sliding puzzle game. The goal is to get the red block out of the board by sliding the other blocks out of the way. Horizontal blocks can only move from side to side and vertical blocks can only move up and down. There are four difficulty levels ranging from easy to expert, each containing 500 puzzles over a total of 2000 puzzles and will keep you challenged and addicted for hundreds of hours. Gradually increasing difficulty which makes this game suitable for kids and adults of all ages. If you like block sliding puzzle games, then you wil definitely enjoy this game!' FROM games WHERE igdb_id = 147488 ON CONFLICT (game_id, language_code) DO NOTHING;
