INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'For Rest', 'A low-poly walking simulator that puts you into a desolate, fully-greyscale forest that is devoid of life. While moving through this world, you must destroy blinking, disruptive roots that are burdening your path and the space around you. Sometimes these roots spawn new life, and sometimes a human, Charlie, appears. As you play through, the world will gradually saturate and life will begin to populate around you.' FROM games WHERE igdb_id = 194376 ON CONFLICT (game_id, language_code) DO NOTHING;
