INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kame Paradise 2', 'Kame Paradise 2, made by Yamamoto Doujin, is a sequel to Kame Paradise, being a Dragon Ball Hentai Game released on November 23rd, 2021. It is part of a series of games made by Yamamoto. It is a R+18 Adult Hentai game featuring Dragon Ball Characters from Dragon Ball: Original, Z, GT, and Super. This entry has character from Original, Z, GT, and Super, as opposed to the first game which mostly just focuses on characters from Original Dragon Ball.' FROM games WHERE igdb_id = 231389 ON CONFLICT (game_id, language_code) DO NOTHING;
