INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-oregon-trail--7', 256238, '2021-04-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7rlr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2r6n.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Oregon Trail', 'The Oregon Trail by Gameloft—Experience The Oregon Trail like never before. A modern twist on the trials and tribulations of the road to Oregon, this official successor to the global phenomenon will immerse players in exhilarating journeys ranging from the historically accurate to the totally extreme. Players will pick their traveling party, stock the wagon with supplies, and embark on an adventure filled with tough choices, new dangers, and unexpected situations. Surviving blizzards, broken limbs, snakebites, exhaustion, starvation, and the dreaded dysentery is no small feat; all the while navigating an untamed frontier to get your party to their new life in Oregon before the winter. Track down a missing party in the aftermath of a fierce blizzard, transport volatile gunpowder through blistering desert heat, compete in challenging hunting mini-games, and meet a broad cast of historic figures. With procedurally selected random events where players’ choices affect their party and future game events, there’s always a new adventure on the horizon every time you play.' FROM games WHERE igdb_id = 256238 ON CONFLICT (game_id, language_code) DO NOTHING;
