INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('slap-the-rocks', 176884, '2021-10-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co40fz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1lsi.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slap the Rocks', 'Slap The Rocks is a new top-down puzzle which will push your brain to the limit. Slap rocks, avoid bushes and flee from stumps! Can you smash your way to the final level? Many levels of complexity! 20 unlocked levels to explore. You choose! Many ways to complete the same puzzle. Beautiful pixel graphics. Captivating and interesting puzzles. The controls are simple and accessible.' FROM games WHERE igdb_id = 176884 ON CONFLICT (game_id, language_code) DO NOTHING;
