INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hero Road Online', 'Hero''s Path is a 3D MMORPG featuring a unique combination of land and naval combat. Players begin by adventuring and defeating monsters on land. Once they accumulate enough funds, they can purchase and upgrade their own warships and venture out to sea. Naval battles not only take place between warships, but also involve close combat aboard ships.' FROM games WHERE igdb_id = 367851 ON CONFLICT (game_id, language_code) DO NOTHING;
