INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WarioWare: Get It Together!', 'Take on over 200 quick and quirky microgames - lightning-fast minigames filled with frantic fun - solo or with a friend! When his latest harebrained business scheme goes awry, Wario must use his signature style (and smell) to fix it. How? By playing a twisted collection microgames of course! From assembling a robot to pulling out a statue''s armpit hair, the WarioWare: Get It Together! game is a comedic, cooperative microgame mashup.' FROM games WHERE igdb_id = 152358 ON CONFLICT (game_id, language_code) DO NOTHING;
