INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shirube no Kazari', 'Shirube No Kazari is a traditional Yume Nikki fangame. You control Michito, who stays in an abandoned facility, keeping watch over a mysterious girl in a chamber. The game does not feature a traditional Nexus, but rather a linear starting area that branches out as the player explores further. There is also a health system wherein the player will be woken up if they''re caught by chasers too many times.' FROM games WHERE igdb_id = 220768 ON CONFLICT (game_id, language_code) DO NOTHING;
