INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Knot Me!', 'Knot Me! is a 3D action-adventure game designed to explore sexual kinks, sexual culture, sexual consent, and other taboo topics. The player controls Regina, a possum-girl, and Señor Edgar, her talking bondage rope. Using Señor Edgar’s ability to tie knots, swing from overhead fixtures, and whip a short distance in front of her, Regina explores the four floors of Red Velvet while on a mission to interview the elusive Spider Queen of Bondage. On the way, she must satisfy three boss characters by appealing to their sexual kinks, culminating with the Spider Queen herself.' FROM games WHERE igdb_id = 146474 ON CONFLICT (game_id, language_code) DO NOTHING;
