INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soran', 'Soran is an arena shooter/RPG hybrid being developed and produced by Joseph Keenan. Use classic shooter weapons like the Sniper or Doob Tube, along side new and unique guns like the Defenestrator to finesse your way to victory in 1v1s, 2v2s, and small scale Battle Royales. When you aren''t competing, you can explore the world of Four Shores discovering collectables, making friends or padding your stats for the next battle. Also there is a flying dog named Friend.' FROM games WHERE igdb_id = 145415 ON CONFLICT (game_id, language_code) DO NOTHING;
