INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('curve-racer', 147616, '2021-01-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57dp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arafg.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Curve Racer', 'Curve Racer is an intense arcade racing game where you need to get the highest score possible. You can acquire an amazing score if you avoid any of the cars or obstacles that come in your way. The vehicle won’t stop, so all you can do is to guide it through all the perils as much as possible. The Curve Racer game brings in lots of cars to choose from, all of which pertain to specific categories. You get to customize your driving experience via numerous car upgrades, and you can also acquire map parts that will make browsing through the world a whole lot easier. Immerse yourself in a cool, fun racing experience only with Curve Racer! Features: Intense arcade racing Upgrade your cars and get map parts 4 game modes, free ride, time trial, single lane and dual lane Use boosters like coins, magnets, high speed or car parts Numerous missions to choose from It’s very easy to change environments!' FROM games WHERE igdb_id = 147616 ON CONFLICT (game_id, language_code) DO NOTHING;
