INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metro Simulator', 'Attention - the train is now arriving at platform 1! You are the train operator and thousands of people rely on you every day on their way to work or home. Take this unique chance to experience Moscow''s subway systems in a whole new way! You control the train just like in real life: Accelerate, brake, open doors, switch cameras, set car functions and many other tasks! Take on the role of a passenger and visit stations, trains and the depot. Will you rise to the challenge and take control deep under the metropolis? Your passengers trust in you, get them to their destination safely and on time!' FROM games WHERE igdb_id = 154904 ON CONFLICT (game_id, language_code) DO NOTHING;
