INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crypto-Shots', 'Crypto-Shots is a browser-based First Person Shooter Play to Earn game native to The WAX blockchain. The project has begun on the 19th of October''21 and has been ever developing since. In Crypto-Shots you can collect weapon parts, blend them into cool NFTs and use them to take down enemies across different planets. Or, if you like adrenaline, even challenge your friends in the arenas.' FROM games WHERE igdb_id = 221844 ON CONFLICT (game_id, language_code) DO NOTHING;
