INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Calluna', 'Calluna is a small adventure game about the Norwegian composer and violinist Ole Bull. In Calluna, you can play as Ole Bull in four independent adventures as young, old, rich, and poor. Walk the streets of Bergen, Paris, and Cairo in first-person and explore a semi-open world filled with interactive items, townspeople, and collectibles. Solve quests based on historical events and follow Ole Bull’s dream of fame and glory.' FROM games WHERE igdb_id = 173248 ON CONFLICT (game_id, language_code) DO NOTHING;
