INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Entangled', 'Entangled is a physics game where you solve puzzles with a grappling gun. It''s a 2D platformer where you''ll be immersed in a colorful environment while being entranced by a relaxing space ambient soundtrack. All this while you think your way through a number of cleverly crafted physics puzzles. These puzzles are challenging and were made specifically to evoke the aha moment in players when figuring out their secrets...' FROM games WHERE igdb_id = 105321 ON CONFLICT (game_id, language_code) DO NOTHING;
