INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fallen Star', 'As the Cannan Empire reaches its way across the islands, conquering territories under the firm hand of the Emperor and a Mysterious Knight named Valles, the Imperial Prince Claude journeys with a girl named Hellen after he witnesses her village massacred by the very people he calls home. Along with a Mercenary and a mysterious Wizard from the Order of Ragnard, Claude and his friends enter the sacred monument of Obelisk seeking the Fallen Star, said to have fell at the top of Obelisk when Ragnard first walked the island, before it falls into the hands of Valles.' FROM games WHERE igdb_id = 202892 ON CONFLICT (game_id, language_code) DO NOTHING;
