INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Lord of the Rings: Rise to War', 'In this Geo-strategic Seasonal Wargame, players will embark on new adventures to build armies for conquest and strategically expand their territory in pursuit of the One Ring. Set in the Third Age of Middle-earth, The Lord of the Rings: Rise to War offers an immersive and faithful rendition of the fictional world of Arda and its vast array of characters - from the Ranger of the North, Aragorn, to the Elven Lord of Rivendell, Elrond. Based on their choices to side with good or evil, players can build either Fellowships or Warbands, and collaborate with other members on razor-sharp attack plans and deeply fortified defenses against their rivals.' FROM games WHERE igdb_id = 174867 ON CONFLICT (game_id, language_code) DO NOTHING;
