INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Save Farty: The Trivia Game', '"Save Farty" represents a real low point in worldwide trivia games. Self-improvement and the advancement of knowledge have given way to idiocy and unbridled masochism. This is perhaps the sickest game that can be enjoyed alone or with friends since Russian Roulette.' FROM games WHERE igdb_id = 142838 ON CONFLICT (game_id, language_code) DO NOTHING;
