INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tribes-of-midgard-deluxe-edition', 153053, '2021-07-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4bhl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1buq.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tribes of Midgard: Deluxe Edition', 'Mythical creatures, deadly spirits, and gigantic brutes threaten to bring on Ragnarök - the end of the world! It''s up to you, a mighty Einherjar, to cut short your glorious feast in Valhalla and return to Midgard. There, you''ll need to become the ultimate Viking and survive - even thrive to save your village, and the world, from total destruction. Luckily, you don''t have to brave it alone: your (mostly) fearless tribe of co-op companions will help you build up village defenses and find treasures through a vast, beautiful real mall while doomsday ticks closer and closer. But don''t let that stop your tribe from having the best apocalypse of your lives. "Surthrive" is the Viking way in Tribes of Midgard, a multiplayer, action-survival RPG of gigantic proportions.' FROM games WHERE igdb_id = 153053 ON CONFLICT (game_id, language_code) DO NOTHING;
