INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('adventure-field-4', 163697, '2021-02-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3l10.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arzj9.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventure Field 4', 'Several years after Atoa defeated his evil self, Eras, and Marok took their place as leaders of the Sarook Kingdom. Atoa defeated the evil that was born from within him but a greater danger is now looming upon Sarook kingdom... The direct sequel to Adventure Field 3... Adventure Field 4 is a 20 hour, semi open-world, turn-based JRPG. Battle monsters, complete quests and save Sarook Kingdom! In this game you will have to fight your way through dungeons and powerful enemies to try gathering souls gems. Between the fighting and the exploration, you can cook and grow some vegetables, discover hidden mysteries hidden within the night and day system, try to find what people need to finish side quests and find many collectibles and secrets along the way! In Adventure Field 4, you can forget the old way of getting gold and items. You will need to find a variety of chests to open at your local chest opener! Having some difficulty with particular enemies in combat? Ask your royal team mate, Eserod! He will tell you about monsters strengths and weakness! You will need his help for sure... Dark hours are coming again to Sarook Kingdom... The Kingdom can feel the burning souls of the calamity... The Kingdom will fall again... But not if you can save it!...' FROM games WHERE igdb_id = 163697 ON CONFLICT (game_id, language_code) DO NOTHING;
