INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Murders on Budapest', 'Doyle, lost in a blizzard, is offered shelter at a grand estate. But when he tries to leave, a murder occurs. Who is the killer? Could it be ... me?! Enough with predictable mysteries! Try the comic murder mystery Murders on Budapest and choose your own mystery. Whoever you think the killer is, you''re in for a surprise.' FROM games WHERE igdb_id = 174285 ON CONFLICT (game_id, language_code) DO NOTHING;
