INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Untitled', 'Untitled is a fun and silly 2d platformer with action elements from Russia with Russians stupid humor. There is no plot or meaning here. Break through the crowds of impersonal dummies to come face to face with such nounames as: GhostlyGirl, Anonymous-speedrunner, Byte, 5opka, Doki Doki quartet and... the developer WheatleyHDD himself' FROM games WHERE igdb_id = 186022 ON CONFLICT (game_id, language_code) DO NOTHING;
