INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Easy Flight Simulator', 'Have you ever dreamed to take commands of fantastic planes like jet, super jumbo, cargo or stunt plane? This game is a real flight simulator with commands designed to be easily taken over at all age. Fly from checkpoints to checkpoints showing your pilot skills in different weather and time of the day conditions and complete all levels. If you always wanted to fly but thought it was over complicated, this game will prove you can do it!' FROM games WHERE igdb_id = 159385 ON CONFLICT (game_id, language_code) DO NOTHING;
