INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gebo', 'Gebo is a first-person game where you play as Alexis, a human stuck in a dreamlike world together with a disembodied voice that calls themselves Selene. Explore the temple, solve puzzles and do your best to find a way out, even if everything isn’t what they seem to be.' FROM games WHERE igdb_id = 178196 ON CONFLICT (game_id, language_code) DO NOTHING;
