INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('my-magic-florist', 146773, '2021-01-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4dkm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arc7m.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Magic Florist', 'My Magic Florist will take you to a world of magic, colors, and harmony. You''ll be tasked to take care of your own enchanted flower shop. Earn money and make upgrades through wise investments! Your magical fairy powers are a good start, but you''ll need to get experience and hone your skills to truly succeed. You''re the only boss, and in the end, it''ll be up to you and your hard work. Can you make it? So, give it a try! Play and learn—great fun guaranteed!' FROM games WHERE igdb_id = 146773 ON CONFLICT (game_id, language_code) DO NOTHING;
