INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Observer: System Redux - Day One Edition', 'Observer: System Redux is the definitive vision of the award-winning cyberpunk thriller, rebuilt and augmented for the next generation. System Redux offers expanded gameplay, which includes new game mechanics, new secrets to find, redesigned stealth, additional neural interrogations, and quality-of-life improvements made with the help of the Observer community. Veteran Observers can also dive deeper into this dystopian reality thanks to three brand-new side cases to solve, adding another layer of depth to the game’s story while exploring thought-provoking themes of a future that soon might become our present.' FROM games WHERE igdb_id = 148017 ON CONFLICT (game_id, language_code) DO NOTHING;
