INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DreamHack Beyond', 'Welcome to DreamHack Beyond, an at-home, all-digital free interactive experience showcasing the best of DreamHack. Players can dive into the story of the mystical Sleepers by creating their own characters, completing the game’s narrative, looking for side quests and building up their XP, farming for items like Cheer Gear, and more! Want to skip the game and get right to the booth you want? No problem!
