INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Captain ToonHead vs. The Punks from Outer Space', 'Ever wanted to beat a T-Rex up with a chancla, while building powerful towers that shoot piñatas, hot sauce and heat-seeking fireworks? Captain ToonHead vs. The Punks from Outer Space is the VR tower defense game of your cartooniest dreams. This is not your diorama-style VR tower defense. This time you’re going to have to move all over the map, hammer away to upgrade your towers, throw over-powered chanclas recklessly and shoot electric beams from weaponized pizza at your enemies. Fight from the front lines!' FROM games WHERE igdb_id = 157712 ON CONFLICT (game_id, language_code) DO NOTHING;
