INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('animal-puzzle-preschool-learning-game-for-kids-and-toddlers', 165618, '2021-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3rk2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar11dc.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animal Puzzle: Preschool Learning Game for Kids and Toddlers', 'This animal plug-in peg puzzle educational game has been specially developed for young children of kindergarten age and for preschoolers. Dear parents: Please note that this game does not require your child to speak any language. The game does not contain any text or speech output and works intuitively using easily understandable symbols and graphics. It is therefore perfectly suitable for all countries and languages! The puzzle game contains many great, funny and unique animal motifs suitable for children. Please note that this puzzle only supports touchscreen functionality. The menu and the scenes can only be played with the touch controls!' FROM games WHERE igdb_id = 165618 ON CONFLICT (game_id, language_code) DO NOTHING;
