INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pathological-tires', 163092, '2021-08-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3iyo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1hck.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pathological Tires', 'In Pathological Tires you''re challenged with finding the route for a car to complete a course in the shortest possible time. Find the optimal balance of minimizing distance and maintaining momentum by avoiding sharp turns and other obstacles. Throughout the game, you''ll have to contend with using different cars and driving on road surfaces with different properties, as well as one-way ramps, boost pads, teleporters, and more. The game features over 200 levels to solve across 4 environments with their own original soundtrack, as well as a fully-featured level editor to create your own challenges.' FROM games WHERE igdb_id = 163092 ON CONFLICT (game_id, language_code) DO NOTHING;
