INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mermaid-castle', 147740, '2021-03-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5akq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbzh.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mermaid Castle', 'The mermaid sisters need your help! Their home, the beautiful Mermaid Castle, was destroyed and its treasure stolen. So hop in, gather coins, watch out for sharks and swim through the beautiful submarine underworld! The Ruthless Shark Gang, led by its ominous boss, Shark the Hammer, raided the Mermaid Castle. The attack left the home of the mermaid sisters in ruins. And what''s worse, all their valuables were stolen! With your help, the sisters will restore their castle to its former glory and get rid of the sharks once and for all! To do that, you will explore eight beautiful underwater locations rich in fascinating plants and wildlife. Rocky bottoms, golden sands, coral reef, ancient ruins and dark caves full of fossils - all this awaits you in your blue-water adventure! Swim, dash and collect coins and treasure. But watch out! Cunning fish and crabs, spiky sea urchins, venomous jellyfish and other aquatic creatures will try to stop you! Dash to quickly avoid danger or collect and throw pearls at enemies. Some of them will leave coins, so grab them! Seek for friendly little fish and avoid rusty anchors or bombs. And if you see a shark... you’d better hide!' FROM games WHERE igdb_id = 147740 ON CONFLICT (game_id, language_code) DO NOTHING;
