INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Family Vacation 2: Road Trip', 'The Simmons family is at it again... they''re taking their camper, hooking it up to their SUV and going on a cross-country camping adventure! You''ll be asked to help pack and get everything they’ll need on their trip and enjoy all that Mother Nature has to offer. Travel through Montana, Idaho, Colorado and more. Visit the most wonderful natural attractions in the world; Yellowstone Park, the Grand Canyon and even catch a glimpse of a UFO near Area 51. Camp out under the stars and get back to nature in this family-friendly Road Trip adventure! - Over 60 hidden object locations - Over 25 themed mini-games and puzzles - Beautiful art and design for all locations - Life-like animations and realistic sound effects - Fully customized controls for Nintendo Switch' FROM games WHERE igdb_id = 54019 ON CONFLICT (game_id, language_code) DO NOTHING;
