INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kathy Rain: Director''s Cut', 'Award-winning adventure Kathy Rain returns in the Director’s Cut, featuring an extended story with more puzzles to solve and new areas to explore. Witness the emergence of an iconic detective as you uncover a dark and sinister truth hiding behind the calm exterior of a small rural town.
