INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '123 Dots', 'The game includes more than 150 educational activities for your child to learn while having fun. 123 Dots also helps children develop important basic skills such as creativity, basic skills, attention span and memory. 123 Dots entertains toddlers while they learn numbers from 1 to 20 with its fun and friendly Dots. In addition to teaching numbers and counting, your children can learn geometric shapes, basic skills, the alphabet and sequences. All in one!' FROM games WHERE igdb_id = 159402 ON CONFLICT (game_id, language_code) DO NOTHING;
