INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ropin-ranch', 279425, '2021-07-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7gyw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scptud.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ropin'' Ranch', 'Welcome to Ropin'' Ranch, the ultimate Free-To-Play online ranch game that invites you to step into the boots of a seasoned rancher. In this expansive world, you''ll take charge of your very own ranch, tame wild horses, and breed horses with real-world genetics. Unlock horses in over 150+ colors and get unique horses every time with markings! Ropin'' Ranch offers an immersive and educational experience, blending the thrill of ranch life with the intricacies of horse genetics, illnesses, and more. Raise goats for meat, milk, or showcase their excellence in the show ring, and for the first time, experience the joys of managing gentle giants - cows! Train your cows for work or show, or raise them for meat or milk and sell them to the rodeo! Ropin'' Ranch also strives to bring awareness to real world problems such as horse overpopulation, wild horse problems, cattle factory farming and more.' FROM games WHERE igdb_id = 279425 ON CONFLICT (game_id, language_code) DO NOTHING;
