INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('get-lost-in-nature-with-luke', 165162, '2021-03-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3lgs.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Get Lost in Nature With Luke', 'America''s East Coast is home to some of the most beautiful canyons, beaches, mountains, gorges, mountains, and rivers. It is especially famous during the Fall, when the leaves turn to impossibly beautiful shades of red, orange and yellow. This experience will allow you to visit some of these beautiful locations, hear a guided narration, and get up and even walk about a bit! At a time when travel, especially international travel, is so hard, we want to make you feel truly transported. We want you to feel the vitality, the rawness of these beautiful places in the same way you''d feel if you were visiting these places for the first time. New places will be added frequently, even extending outside the United States. Come and be part of this exciting journey with us!' FROM games WHERE igdb_id = 165162 ON CONFLICT (game_id, language_code) DO NOTHING;
