INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Last Stop: Station 66', 'You fell asleep during a train ride after visiting your friend. Upon awakening you realize you''ve arrived at the last stop, except this line shouldn''t have more than 25 stops, but you''ve now arrived at Station 66. Uncover the mystery behind what is actually going on, and go in depth with the multiple outcomes to your story and ultimately your demise.
