INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Curse That Magic Cat!', 'Magnus the Wizard has cursed you, turning you into a cat! Lift your curse and take your revenge by meowing, hiding, destroying things, and collecting spell books to break the spell. Curse That Magic Cat! is a lighthearted, single-player game made by students at SMU Guildhall.' FROM games WHERE igdb_id = 142236 ON CONFLICT (game_id, language_code) DO NOTHING;
