INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Madrid Noir', 'Madrid Noir is a 45 minute mystery adventure that unfolds across two acts in this VR film. With her uncle declared dead, a disenchanted young woman must delve into her memories to pick up his shadowy trail. Solving the puzzles of the past ain''t gonna be easy!' FROM games WHERE igdb_id = 181050 ON CONFLICT (game_id, language_code) DO NOTHING;
