INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deathloop', 'Deathloop transports players to the lawless island of Blackreef in an eternal struggle between two extraordinary assassins. Explore stunning environments and meticulously designed levels in an immersive gameplay experience that lets you approach every situation any way you like. Hunt down targets all over the island in an effort to put an end to the cycle once and for all, and remember, if at first you don’t succeed… die, die again.' FROM games WHERE igdb_id = 113598 ON CONFLICT (game_id, language_code) DO NOTHING;
