INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvel Future Revolution', 'Marvel Future Revolution is Marvel’s first Open World RPG mobile game, featuring an original storyline with fan-favorite Marvel Super Heroes and Super Villains. Written by veteran comics writer Marc Sumerak (Avengers, Thor, Iron Man, Fantastic Four, Black Panther, Captain Marvel, etc.), Marvel Future Revolution begins with numerous Earths converging across multi-dimensions to form an entirely new ‘Primary Earth.’ As agents of the newly formed ‘Omega Flight’ Super Hero team, players will work together to battle an onslaught of Super Villains, confront their nefarious behaviors and defend the universe.' FROM games WHERE igdb_id = 131743 ON CONFLICT (game_id, language_code) DO NOTHING;
