INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('connect-bricks', 153827, '2021-07-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3ds8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aru2t.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Connect Bricks', 'Connect bricks with matching colors and cover the entire board with bricks to solve each puzzle. But watch out, connections will break if they cross or overlap! Each puzzle has a grid of squares with colored bricks occupying some of the squares. The objective is to connect bricks of the same color by drawing connections between them such that the entire grid is occupied by bricks. However, connections may not intersect. Difficulty is determined by the size of the grid, ranging from 5x5 to 14x14 squares. Play through more than 2000 puzzless. Connect Bricks gameplay ranges from simple and relaxed, to challenging and frenetic. This puzzle game is a great mind practice.' FROM games WHERE igdb_id = 153827 ON CONFLICT (game_id, language_code) DO NOTHING;
