INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'VaporLight: Drifter', 'Welcome to the VaporLight Void, a place many Racers find themselves in sooner or later. You don''t know how you ended up here and you don''t know what to do with yourself. That''s fine. You won''t find guidance here, but maybe you can find it in yourself.' FROM games WHERE igdb_id = 186267 ON CONFLICT (game_id, language_code) DO NOTHING;
