INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jester / King', 'You play the amnesiac jester Madion who woke up next to the king''s lifeless body. A curse has fallen upon the kingdom, annihilating almost everyone, and driving the survivors to madness. Madion is torn between seeking the truth, helping the others, and a desire to escape.' FROM games WHERE igdb_id = 166745 ON CONFLICT (game_id, language_code) DO NOTHING;
