INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA Now 22', 'Com2Us has just released a brand new officially licensed NBA game called NBA Now 22, as a basketball simulator of sorts, where players can choose from their favorite teams and recruit their dream players to create powerful squads and serve their opponents on the court. In essence, this game is similar to FIFA Mobile, especially in the fact that your players are represented by cards that you can obtain, and the matches themselves are very short and focus only on pivotal moments of the game, such as rebounds, steals, blocks, and scoring opportunities.' FROM games WHERE igdb_id = 303806 ON CONFLICT (game_id, language_code) DO NOTHING;
