INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Biomutant', 'Biomutant is an open-world, post-apocalyptic Kung-Fu fable RPG, with a unique martial arts styled combat system allowing you to mix melee, shooting and mutant ability action. A plague is ruining the land and the Tree-of-Life is bleeding death from its roots. The Tribes stand divided. Explore a world in turmoil and define its fate, will you be its savior or lead it to an even darker destiny?' FROM games WHERE igdb_id = 54842 ON CONFLICT (game_id, language_code) DO NOTHING;
