INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Colony Battle', 'A real-time-strategy game about conquering rival ant colonies. Larger colonies generate ants faster, and there are special colonies along the way which allow for strategic play. There are 40 developer levels, an infinitely random arcade mode, and user-created levels. There are ways to customize your colors and bug type as well.' FROM games WHERE igdb_id = 145686 ON CONFLICT (game_id, language_code) DO NOTHING;
