INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Genso Wanderer: Lotus Labyrinth R', 'Venture into dungeons with a huge party of your favorite Touhou characters! This is a dungeon-crawler RPG with an absurdly large party size! The dungeon-crawler RPG Genso Wanderer is now a game with an Oversized Party System that pushes the envelope of the roguelike genre! Now you can bring dozens of partners with you on your dungeon crawls, in addition to other quality of life improvements that make the game''s systems and controls smoother than ever. Overwhelm your enemies with strength in numbers! Lead tons of your favorite Touhou characters at once and conquer the impregnable Lotus Labyrinth!' FROM games WHERE igdb_id = 173124 ON CONFLICT (game_id, language_code) DO NOTHING;
