INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Smashing the Battle Ghost Soul', 'Smashing the Battle is a hack-and-slash action game. You battle against robots using standard attacks, as well as combo attacks. By crushing the enemy, you can open up the way forward. By attacking the enemy, you can gain skill points, allowing you to unleash devastating attacks on large groups of enemies all at once. After clearing each stage, use the coins you have collected to strengthen your character, allowing you to take on even more enemies. You can also use coins to purchase different costumes with various abilities.' FROM games WHERE igdb_id = 165617 ON CONFLICT (game_id, language_code) DO NOTHING;
