INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('a-train-all-aboard-tourism', 146014, '2021-03-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4dg6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar92q.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A-Train All Aboard! Tourism', 'A-Train, the classic urban development simulation game that allows you to create the city of your dreams, is now available on the Nintendo Switch! Become the president of your very own railroad company, laying tracks and running your trains as you see fit. However, you will be responsible for more than the railroad. You''ll also be tasked with managing subsidiaries, playing the stock market, and participating in urban planning, in order to develop and expand your town. This latest installment in the A-Train series introduces the element of tourism to the urban planning formula, and focuses on building up towns into bustling tourism capitals. Providing realistic business management simulations of financing, investing, and more, as well as a wide variety of customizable options for all your vehicles, A-Train: All Aboard! Tourism is packed full of features for you to explore. But don''t be overwhelmed—players old and new alike will be able to jump right into the series thanks to the fun and practical tutorials provided in the early stages. So why not hop aboard the A-Train with your trusted team of advisors, and start crafting a bright future for your town?' FROM games WHERE igdb_id = 146014 ON CONFLICT (game_id, language_code) DO NOTHING;
