INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('island-farmer', 178806, '2021-04-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5997.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar184w.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Island Farmer', 'Farms are set up in islands over calm and clear water. In this tiny fantasy experience, that is easy to do and very relaxing, just like a 3D jigsaw puzzle. Carefully observe the island, try to memorize it, then shuffle the blocks. Swap blocks to reproduce the desired island and it will compose the archipelago. There is no time limit, no logic challenges, nor resources to manage, so you can calmly just focus on the core mechanics while listening to a soothing soundtrack.' FROM games WHERE igdb_id = 178806 ON CONFLICT (game_id, language_code) DO NOTHING;
