INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Faircroft''s Antiques: Home for Christmas - Collector''s Edition', 'Mia Faircroft''s Hidden Object travels continue! With her friend Maria Wise in tow, Mia returns to her family for a well-earned break. But home is not without its fair share of problems, and soon she gets to work to rescue the holidays! Explore vividly realized hidden object scenes, restore works of art in fun minigames, and bring joy this season in Faircroft''s Antiques: Home for Christmas!' FROM games WHERE igdb_id = 147755 ON CONFLICT (game_id, language_code) DO NOTHING;
