INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jack Jeanne', 'Jack Jeanne is an opera-themed otome game, produced and illustrated by Sui Ishida (Tokyo Ghoul) and co-written by Ishida and Shin Towada (Tokyo Ghoul light novels). Protagonist Kisa Tachibana is given an opportunity to fulfill her dream of going to the All Boys Univeil Drama School where she must develop bonds and rivalries with her classmates while hiding her identity as a girl.' FROM games WHERE igdb_id = 117675 ON CONFLICT (game_id, language_code) DO NOTHING;
