INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animal Learning Puzzle for Toddlers and Kids', 'In this easy to use animal puzzle game, toddlers and kids can learn the pronunciation and spelling of over 80 animals from around the world. All voice recordings are done by 100% native speakers. The game can be customized to offer different difficulty settings, so children of a great age range can enjoy the puzzles. The spoken languages include: * american english * british english * french * german * italian * european spanish * latin american spanish * european portuguese * brazilian portuguese * dutch * russian Japanese and Chinese languages are coming soon!' FROM games WHERE igdb_id = 147939 ON CONFLICT (game_id, language_code) DO NOTHING;
