INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Death Box', 'Death Box is a labyrinth horror game where the goal is to escape the death box and manage to survive. You have to find the exit of a huge maze of secret rooms and doors without getting caught by zombies and traps. There are 2 types of enemies: fast and slow zombies.' FROM games WHERE igdb_id = 160302 ON CONFLICT (game_id, language_code) DO NOTHING;
