INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lyre', 'Lyre is a romance furry visual novel story where you travel to a strange kingdom as a human ambassador, surrounded by diverse characters. Your only weakness is that you have no idea what their motives are. They''re all deceiving each other and every one of them is better at it than you. You find yourself only able to trust the most unlikely individual as a terrible plot unfolds around you.' FROM games WHERE igdb_id = 182275 ON CONFLICT (game_id, language_code) DO NOTHING;
