INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Warriors 5', 'Experience exhilarating action set in a dramatic historical setting in SAMURAI WARRIORS 5. As the latest numbered entry in the SAMURAI WARRIORS franchise, the story, characters, and visuals have been re-imagined to set the stage for a thrilling new series. The story takes place after the Ōnin War during the golden age of the Sengoku period, and features a story that centers on the lives of two of the most representative military commanders of this era: Nobunaga Oda and Mitsuhide Akechi.' FROM games WHERE igdb_id = 143608 ON CONFLICT (game_id, language_code) DO NOTHING;
