INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Flipper', 'Don''t miss out on this epic pinball adventure! Everything you love about pinball packed into an action RPG! Experience pinball like you never have before! Ready, aim, fire! Time your attacks right and crush your foes before they know what hit ''em. Activate skills to maximize damage! Travel across several worlds, each with its own friends to meet and mysteries to unravel! In World Flipper, units can pair up and combine their abilities.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 130653 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
