INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars Galaxies Restoration', 'A non-profit, fan-made, community-driven remaster of the classic MMORPG Star Wars Galaxies: An Empire Divided. Featuring a return to the multi-profession system and the combat style of the Combat Upgrade, combined with all NGE content and expansions, and regularly published new and exciting content additions and quality of life improvements, this classic free-to-play is ready to take you back to the best Star Wars Saga ever told: Yours.' FROM games WHERE igdb_id = 191026 ON CONFLICT (game_id, language_code) DO NOTHING;
