INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Praesidium', 'Praesidium is a third-person, speedrunner, action platformer set on the rooftops of a futuristic city. Make your way through the city with the help of your advanced shield that can create hovering gravity fields to launch you forward. Dodge and block turrets as they try to stun you and slow you down. Move as fast as possible through the level to set your best time.' FROM games WHERE igdb_id = 145758 ON CONFLICT (game_id, language_code) DO NOTHING;
